arguments.command:
cd /tmp/sv-1629df712e5b4161bbc95ce4912af76c
# The dynamic symbols are too sparse. Let's look at ALL symbols (local/global) of type FUNC near 0x2f4b20
aarch64-linux-gnu-readelf -sW _.debug | awk '
$2 ~ /^[0-9a-f]+$/ && $4 == "FUNC" {
  addr=strtonum("0x"$2); size=strtonum($3)
  if (addr > 0 && addr <= 0x2f4b20 && (0x2f4b20 - addr) < 0x2000) {
    printf "%s at 0x%x size %d (offset +0x%x)\n", $8, addr, size, 0x2f4b20 - addr
  }
}'
echo "==="
