arguments.command:
cd /tmp/sv-1629df712e5b4161bbc95ce4912af76c
# Maybe those addresses are in a data section (BSS/rodata). Let's check what section they're in
aarch64-linux-gnu-readelf -SW _.debug | grep -E "^\s+\[" | awk '{
  if ($4 ~ /^[0-9a-f]+$/) {
    addr=strtonum("0x"$4); size=strtonum("0x"$6)
    if (addr <= 0x2f4b20 && addr+size > 0x2f4b20) print "0x2f4b20 in section:", $2, "addr:", $4, "size:", $6
  }
}'
echo "---"
# Simpler: just use objdump --section-headers
aarch64-linux-gnu-objdump -h _.debug | awk '{if (NF>=6 && $2 !~ /^[0-9]/) {size=strtonum("0x"$3); vma=strtonum("0x"$4); if (vma <= 0x2f4b20 && vma+size > 0x2f4b20) print "0x2f4b20 in:", $2, "vma:", $4, "size:", $3}}'
aarch64-linux-gnu-objdump -h _.debug | awk '{if (NF>=6 && $2 !~ /^[0-9]/) {size=strtonum("0x"$3); vma=strtonum("0x"$4); if (vma <= 0x2f4c84 && vma+size > 0x2f4c84) print "0x2f4c84 in:", $2, "vma:", $4, "size:", $3}}'

